userContent.text:
Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<div><strong>Axial loading of a rod</strong></div>
<div id="loadingMode">
  <span>Loading mode</span>
  <button id="modeTension" class="active">Tension</button>
  <button id="modeCompression">Compression</button>
</div>
<label>
  Applied force F
  <input id="appliedForce" type="range" min="-1" max="1" step="0.05" value="0.55">
  <span id="forceReadout">F = +0.55</span>
</label>
<div>
  <button id="step0">Step 1</button>
  <button id="step1">Step 2</button>
  <button id="step2">Step 3</button>
</div>
<div id="stepTitle" style="font-weight:bold;">Tension: positive ΔL</div>
<div id="stepNarration" style="line-height:1.35;">The red arrows pull outward from the rod ends.</div>
<div style="font-size:11px;line-height:1.35;">ΔL = F L₀ / (Y A), with constant A.</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// cylinder side wall → CylinderGeometry(R,R,L) open-ended with pale blue-lavender vertex gradient
// top circular face → CircleGeometry(R) horizontal translucent disk at deformed top y = L
// top and bottom rims → circular Line geometry in horizontal XZ planes
// dashed reference ellipse → dashed circular Line at undeformed top y = L0
// tension extension guides → two dashed vertical Line segments from y=L0 to y=L
// red axial forces → two vertical cylinder-and-cone arrow Groups, direction set by loading sign
// original length bracket L0 → black vertical Line with two horizontal tick Lines at x=-0.95
// length-change bracket ΔL → black vertical Line with tick Lines, left in tension and right in compression
// labels → addLabel entries for F⃗, ΔL, L₀, panel mark, and compression cross-section area A
// area leader → black QuadraticBezier Line with cone arrowhead pointing to top face in compression

const R = 0.55;
const L0 = 3.2;
const DL_SCALE = 0.55;
const rimColor = 0x7f93b3;
const redColor = 0xc93336;
const blackColor = 0x111111;
let loadingModeState = 'Tension';

const mainGroup = new THREE.Group();
scene.add(mainGroup);

const sideMat = new THREE.MeshBasicMaterial({
  vertexColors: true,
  transparent: true,
  opacity: 0.88,
  side: THREE.DoubleSide
});
const topMat = new THREE.MeshBasicMaterial({
  color: 0xd6ddf2,
  transparent: true,
  opacity: 0.78,
  side: THREE.DoubleSide
});
const rimMat = new THREE.LineBasicMaterial({ color: rimColor, depthTest: false });
const dashMat = new THREE.LineDashedMaterial({
  color: rimColor,
  dashSize: 0.07,
  gapSize: 0.045,
  depthTest: false
});
const dimMat = new THREE.LineBasicMaterial({ color: blackColor, depthTest: false });
const leaderMat = new THREE.LineBasicMaterial({ color: blackColor, depthTest: false });
const redMat = new THREE.MeshBasicMaterial({ color: redColor, depthTest: false });

function makeSideGeometry(len) {
  const geom = new THREE.CylinderGeometry(R, R, Math.max(0.02, len), 96, 18, true);
  const pos = geom.attributes.position;
  const base = new THREE.Color('#d6ddf2');
  const colors = [];
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i);
    const z = pos.getZ(i);
    const edge = Math.abs(x) / R;
    const rearDarken = z < 0 ? 0.93 : 1.0;
    const shade = (0.82 + 0.23 * (1 - Math.min(edge, 1))) * rearDarken;
    colors.push(
      Math.min(1, base.r * shade),
      Math.min(1, base.g * shade),
      Math.min(1, base.b * shade)
    );
  }
  geom.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
  geom.computeVertexNormals();
  return geom;
}

function makeCircleLine(y, material, dashed = false) {
  const pts = [];
  const n = 144;
  for (let i = 0; i <= n; i++) {
    const a = (i / n) * Math.PI * 2;
    pts.push(new THREE.Vector3(R * Math.cos(a), y, R * Math.sin(a)));
  }
  const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), material);
  if (dashed) line.computeLineDistances();
  line.renderOrder = 10;
  return line;
}

function replaceLinePoints(line, pts, dashed = false) {
  const old = line.geometry;
  line.geometry = new THREE.BufferGeometry().setFromPoints(pts);
  old.dispose();
  if (dashed) line.computeLineDistances();
}

function circlePoints(y) {
  const pts = [];
  const n = 144;
  for (let i = 0; i <= n; i++) {
    const a = (i / n) * Math.PI * 2;
    pts.push(new THREE.Vector3(R * Math.cos(a), y, R * Math.sin(a)));
  }
  return pts;
}

const sideMesh = new THREE.Mesh(makeSideGeometry(L0 + DL_SCALE * 0.55), sideMat);
sideMesh.position.y = (L0 + DL_SCALE * 0.55) / 2;
sideMesh.renderOrder = 1;
mainGroup.add(sideMesh);

const topDisk = new THREE.Mesh(new THREE.CircleGeometry(R, 128), topMat);
topDisk.rotation.x = -Math.PI / 2;
topDisk.renderOrder = 3;
mainGroup.add(topDisk);

const topRim = makeCircleLine(L0, rimMat);
const bottomRim = makeCircleLine(0, rimMat);
const refEllipse = makeCircleLine(L0, dashMat, true);
mainGroup.add(topRim, bottomRim, refEllipse);

const guideLeft = new THREE.Line(new THREE.BufferGeometry(), dashMat);
const guideRight = new THREE.Line(new THREE.BufferGeometry(), dashMat);
guideLeft.renderOrder = guideRight.renderOrder = 12;
mainGroup.add(guideLeft, guideRight);

function makeArrowGroup() {
  const g = new THREE.Group();
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.025, 0.025, 1, 20), redMat);
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.085, 0.24, 28), redMat);
  g.add(shaft, cone);
  g.renderOrder = 20;
  mainGroup.add(g);
  return { group: g, shaft, cone };
}

const topArrow = makeArrowGroup();
const bottomArrow = makeArrowGroup();

function setVerticalArrow(arrow, tailY, tipY) {
  const len = Math.abs(tipY - tailY);
  const sign = tipY >= tailY ? 1 : -1;
  const coneLen = Math.min(0.24, len * 0.38);
  const shaftLen = Math.max(0.001, len - coneLen);
  arrow.group.visible = len > 0.03;
  arrow.shaft.geometry.dispose();
  arrow.shaft.geometry = new THREE.CylinderGeometry(0.025, 0.025, shaftLen, 20);
  const baseY = tipY - sign * coneLen;
  arrow.shaft.position.set(0, (tailY + baseY) / 2, 0);
  arrow.cone.position.set(0, tipY - sign * coneLen / 2, 0);
  arrow.cone.rotation.set(sign > 0 ? 0 : Math.PI, 0, 0);
}

function makeBracketGroup() {
  const g = new THREE.Group();
  const v = new THREE.Line(new THREE.BufferGeometry(), dimMat);
  const t0 = new THREE.Line(new THREE.BufferGeometry(), dimMat);
  const t1 = new THREE.Line(new THREE.BufferGeometry(), dimMat);
  g.add(v, t0, t1);
  g.userData = { v, t0, t1 };
  g.renderOrder = 30;
  mainGroup.add(g);
  return g;
}

const l0Bracket = makeBracketGroup();
const deltaBracket = makeBracketGroup();

function updateBracket(g, x, yA, yB, tick = 0.22) {
  replaceLinePoints(g.userData.v, [new THREE.Vector3(x, yA, 0), new THREE.Vector3(x, yB, 0)]);
  replaceLinePoints(g.userData.t0, [new THREE.Vector3(x - tick / 2, yA, 0), new THREE.Vector3(x + tick / 2, yA, 0)]);
  replaceLinePoints(g.userData.t1, [new THREE.Vector3(x - tick / 2, yB, 0), new THREE.Vector3(x + tick / 2, yB, 0)]);
}

const leaderGroup = new THREE.Group();
const leaderLine = new THREE.Line(new THREE.BufferGeometry(), leaderMat);
const leaderCone = new THREE.Mesh(new THREE.ConeGeometry(0.055, 0.15, 20), new THREE.MeshBasicMaterial({ color: blackColor, depthTest: false }));
leaderGroup.add(leaderLine, leaderCone);
leaderGroup.renderOrder = 35;
mainGroup.add(leaderGroup);

function updateLeader(len) {
  const start = new THREE.Vector3(0.92, len + 0.30, 0.18);
  const control = new THREE.Vector3(0.72, len + 0.09, 0.38);
  const end = new THREE.Vector3(0.30, len + 0.018, 0.30);
  const curve = new THREE.QuadraticBezierCurve3(start, control, end);
  const pts = curve.getPoints(36);
  replaceLinePoints(leaderLine, pts);
  const tangent = end.clone().sub(pts[pts.length - 2]).normalize();
  leaderCone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), tangent);
  leaderCone.position.copy(end).sub(tangent.multiplyScalar(0.075));
}

registerInteractive(sideMesh, {
  title: 'Rod deformation',
  tooltip: 'Click: signed axial strain',
  body: 'The rod length changes by ΔL. In this elastic model, ΔL is proportional to F, while the circular cross-section area A stays constant.'
});
registerInteractive(topDisk, {
  title: 'Cross-sectional area A',
  tooltip: 'Click: area held constant',
  body: 'The top face represents the cross-sectional area A used in ΔL = F L₀ / (Y A). Here the radius is fixed as the force changes.'
});

const modeWrap = document.getElementById('loadingMode');
const modeTensionBtn = document.getElementById('modeTension');
const modeCompressionBtn = document.getElementById('modeCompression');
const forceSlider = document.getElementById('appliedForce');
const forceReadout = document.getElementById('forceReadout');
const stepTitleEl = document.getElementById('stepTitle');
const stepNarrationEl = document.getElementById('stepNarration');

const demoSteps = [
  {
    title: 'Tension: positive ΔL',
    narration: 'The red arrows pull outward from the rod ends. The solid cylinder is longer than L₀, so the dashed reference top sits below the new top extension and ΔL is positive.',
    state: { loadingMode: 'Tension', appliedForce: 0.65 }
  },
  {
    title: 'Zero load: undeformed length',
    narration: 'At F = 0 the dashed reference ellipse coincides with the top face. The measured length change collapses to zero while the radius remains unchanged.',
    state: { loadingMode: 'Tension', appliedForce: 0 }
  },
  {
    title: 'Compression: negative ΔL',
    narration: 'The red arrows press inward toward the rod. The rod shortens, so the dashed reference top lies above the new top face and ΔL is negative relative to L₀.',
    state: { loadingMode: 'Compression', appliedForce: -0.65 }
  }
];

let labelFTop, labelFBottom, labelDelta, labelL0, labelPanel, labelArea;

function syncModeButtons() {
  modeTensionBtn.classList.toggle('active', loadingModeState === 'Tension');
  modeCompressionBtn.classList.toggle('active', loadingModeState === 'Compression');
  modeWrap.setAttribute('data-value', loadingModeState);
}

function signedForce() {
  return parseFloat(forceSlider.value);
}

function updateFigure() {
  const f = signedForce();
  const absF = Math.abs(f);
  if (f > 0.0001) loadingModeState = 'Tension';
  if (f < -0.0001) loadingModeState = 'Compression';
  const isTension = f > 0.0001 || (Math.abs(f) <= 0.0001 && loadingModeState === 'Tension');
  const dL = DL_SCALE * f;
  const len = L0 + dL;
  const forceLen = absF > 0.02 ? 0.45 + 0.42 * absF : 0;

  const oldGeom = sideMesh.geometry;
  sideMesh.geometry = makeSideGeometry(len);
  oldGeom.dispose();
  sideMesh.position.y = len / 2;

  topDisk.position.y = len;
  replaceLinePoints(topRim, circlePoints(len));
  replaceLinePoints(bottomRim, circlePoints(0));
  replaceLinePoints(refEllipse, circlePoints(L0), true);

  if (isTension && dL > 0.015) {
    guideLeft.visible = guideRight.visible = true;
    replaceLinePoints(guideLeft, [new THREE.Vector3(-R, L0, 0), new THREE.Vector3(-R, len, 0)], true);
    replaceLinePoints(guideRight, [new THREE.Vector3(R, L0, 0), new THREE.Vector3(R, len, 0)], true);
  } else {
    guideLeft.visible = guideRight.visible = false;
  }

  if (forceLen > 0) {
    if (isTension) {
      setVerticalArrow(topArrow, len + 0.18, len + 0.18 + forceLen);
      setVerticalArrow(bottomArrow, -0.18, -0.18 - forceLen);
    } else {
      setVerticalArrow(topArrow, len + 0.18 + forceLen, len + 0.18);
      setVerticalArrow(bottomArrow, -0.18 - forceLen, -0.18);
    }
    topArrow.group.visible = bottomArrow.group.visible = true;
  } else {
    topArrow.group.visible = bottomArrow.group.visible = false;
  }

  updateBracket(l0Bracket, -0.95, 0, L0);
  const deltaX = isTension ? -0.95 : 0.95;
  updateBracket(deltaBracket, deltaX, L0, len);
  deltaBracket.visible = Math.abs(dL) > 0.018;

  leaderGroup.visible = !isTension;
  if (!isTension) updateLeader(len);

  forceReadout.textContent = `F = ${f >= 0 ? '+' : ''}${f.toFixed(2)}`;
  syncModeButtons();

  if (labelFTop) {
    labelFTop.pos.set(0.17, isTension ? len + 0.18 + forceLen * 0.75 : len + 0.18 + forceLen * 0.55, 0);
    labelFBottom.pos.set(0.17, isTension ? -0.18 - forceLen * 0.75 : -0.18 - forceLen * 0.55, 0);
    labelFTop.div.style.visibility = forceLen > 0 ? 'visible' : 'hidden';
    labelFBottom.div.style.visibility = forceLen > 0 ? 'visible' : 'hidden';

    labelDelta.pos.set(deltaX + (isTension ? -0.20 : 0.20), (L0 + len) / 2, 0);
    labelDelta.div.style.visibility = Math.abs(dL) > 0.018 ? 'visible' : 'hidden';

    labelL0.pos.set(-1.17, L0 / 2, 0);
    labelPanel.pos.set(0, -0.62, 0);
    labelPanel.div.innerHTML = isTension ? '(a)' : '(b)';

    labelArea.pos.set(0.98, len + 0.36, 0.18);
    labelArea.div.style.visibility = !isTension ? 'visible' : 'hidden';
  }
}

modeTensionBtn.addEventListener('click', () => {
  loadingModeState = 'Tension';
  const mag = Math.abs(parseFloat(forceSlider.value));
  forceSlider.value = mag.toFixed(2);
  updateFigure();
});
modeCompressionBtn.addEventListener('click', () => {
  loadingModeState = 'Compression';
  const mag = Math.abs(parseFloat(forceSlider.value));
  forceSlider.value = (-mag).toFixed(2);
  updateFigure();
});
forceSlider.addEventListener('input', updateFigure);

let tweenRAF = null;
function goToStep(index) {
  const step = demoSteps[index];
  if (!step) return;
  if (tweenRAF) cancelAnimationFrame(tweenRAF);
  stepTitleEl.textContent = step.title;
  stepNarrationEl.textContent = step.narration;
  loadingModeState = step.state.loadingMode;
