  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.085, 0.24, 28), redMat);
  g.add(shaft, cone);
  g.renderOrder = 20;
  mainGroup.add(g);
  return { group: g, shaft, cone };
}

const topArrow = makeArrowGroup();
const bottomArrow = makeArrowGroup();

function setVerticalArrow(arrow, tailY, tipY) {
  const len = Math.abs(tipY - tailY);
  const sign = tipY >= tailY ? 1 : -1;
  const coneLen = Math.min(0.24, len * 0.38);
  const shaftLen = Math.max(0.001, len - coneLen);
  arrow.group.visible = len > 0.03;
  arrow.shaft.geometry.dispose();
  arrow.shaft.geometry = new THREE.CylinderGeometry(0.025, 0.025, shaftLen, 20);
  const baseY = tipY - sign * coneLen;
  arrow.shaft.position.set(0, (tailY + baseY) / 2, 0);
  arrow.cone.position.set(0, tipY - sign * coneLen / 2, 0);
  arrow.cone.rotation.set(sign > 0 ? 0 : Math.PI, 0, 0);
}

function makeBracketGroup() {
  const g = new THREE.Group();
  const v = new THREE.Line(new THREE.BufferGeometry(), dimMat);
  const t0 = new THREE.Line(new THREE.BufferGeometry(), dimMat);
  const t1 = new THREE.Line(new THREE.BufferGeometry(), dimMat);
  g.add(v, t0, t1);
  g.userData = { v, t0, t1 };
  g.renderOrder = 30;
  mainGroup.add(g);
  return g;
}

const l0Bracket = makeBracketGroup();
const deltaBracket = makeBracketGroup();

function updateBracket(g, x, yA, yB, tick = 0.22) {
  replaceLinePoints(g.userData.v, [new THREE.Vector3(x, yA, 0), new THREE.Vector3(x, yB, 0)]);
  replaceLinePoints(g.userData.t0, [new THREE.Vector3(x - tick / 2, yA, 0), new THREE.Vector3(x + tick / 2, yA, 0)]);
  replaceLinePoints(g.userData.t1, [new THREE.Vector3(x - tick / 2, yB, 0), new THREE.Vector3(x + tick / 2, yB, 0)]);
}

const leaderGroup = new THREE.Group();
const leaderLine = new THREE.Line(new THREE.BufferGeometry(), leaderMat);
const leaderCone = new THREE.Mesh(new THREE.ConeGeometry(0.055, 0.15, 20), new THREE.MeshBasicMaterial({ color: blackColor, depthTest: false }));
leaderGroup.add(leaderLine, leaderCone);
leaderGroup.renderOrder = 35;
mainGroup.add(leaderGroup);

function updateLeader(len) {
  const start = new THREE.Vector3(0.92, len + 0.30, 0.18);
  const control = new THREE.Vector3(0.72, len + 0.09, 0.38);
  const end = new THREE.Vector3(0.30, len + 0.018, 0.30);
  const curve = new THREE.QuadraticBezierCurve3(start, control, end);
  const pts = curve.getPoints(36);
  replaceLinePoints(leaderLine, pts);
  const tangent = end.clone().sub(pts[pts.length - 2]).normalize();
  leaderCone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), tangent);
  leaderCone.position.copy(end).sub(tangent.multiplyScalar(0.075));
}

