function updateFigure() {
  const f = signedForce();
  const absF = Math.abs(f);
  if (f > 0.0001) loadingModeState = 'Tension';
  if (f < -0.0001) loadingModeState = 'Compression';
  const isTension = f > 0.0001 || (Math.abs(f) <= 0.0001 && loadingModeState === 'Tension');
  const dL = DL_SCALE * f;
  const len = L0 + dL;
  const forceLen = absF > 0.02 ? 0.45 + 0.42 * absF : 0;

