  if (isTension && dL > 0.015) {
    guideLeft.visible = guideRight.visible = true;
    replaceLinePoints(guideLeft, [new THREE.Vector3(-R, L0, 0), new THREE.Vector3(-R, len, 0)], true);
    replaceLinePoints(guideRight, [new THREE.Vector3(R, L0, 0), new THREE.Vector3(R, len, 0)], true);
  } else {
    guideLeft.visible = guideRight.visible = false;
  }

  if (forceLen > 0) {
    if (isTension) {
      setVerticalArrow(topArrow, len + 0.18, len + 0.18 + forceLen);
      setVerticalArrow(bottomArrow, -0.18, -0.18 - forceLen);
    } else {
      setVerticalArrow(topArrow, len + 0.18 + forceLen, len + 0.18);
      setVerticalArrow(bottomArrow, -0.18 - forceLen, -0.18);
    }
    topArrow.group.visible = bottomArrow.group.visible = true;
  } else {
    topArrow.group.visible = bottomArrow.group.visible = false;
  }

  updateBracket(l0Bracket, -0.95, 0, L0);
  const deltaX = isTension ? -0.95 : 0.95;
  updateBracket(deltaBracket, deltaX, L0, len);
  deltaBracket.visible = Math.abs(dL) > 0.018;

  leaderGroup.visible = !isTension;
  if (!isTension) updateLeader(len);

  forceReadout.textContent = `F = ${f >= 0 ? '+' : ''}${f.toFixed(2)}`;
  syncModeButtons();

  if (labelFTop) {
    labelFTop.pos.set(0.17, isTension ? len + 0.18 + forceLen * 0.75 : len + 0.18 + forceLen * 0.55, 0);
    labelFBottom.pos.set(0.17, isTension ? -0.18 - forceLen * 0.75 : -0.18 - forceLen * 0.55, 0);
    labelFTop.div.style.visibility = forceLen > 0 ? 'visible' : 'hidden';
    labelFBottom.div.style.visibility = forceLen > 0 ? 'visible' : 'hidden';

    labelDelta.pos.set(deltaX + (isTension ? -0.20 : 0.20), (L0 + len) / 2, 0);
    labelDelta.div.style.visibility = Math.abs(dL) > 0.018 ? 'visible' : 'hidden';

    labelL0.pos.set(-1.17, L0 / 2, 0);
    labelPanel.pos.set(0, -0.62, 0);
    labelPanel.div.innerHTML = isTension ? '(a)' : '(b)';

    labelArea.pos.set(0.98, len + 0.36, 0.18);
    labelArea.div.style.visibility = !isTension ? 'visible' : 'hidden';
  }
}

