function goToStep(index) {
  const step = demoSteps[index];
  if (!step) return;
  if (tweenRAF) cancelAnimationFrame(tweenRAF);
  stepTitleEl.textContent = step.title;
  stepNarrationEl.textContent = step.narration;
  loadingModeState = step.state.loadingMode;
  const start = parseFloat(forceSlider.value);
  const end = step.state.appliedForce;
  const t0 = performance.now();
  const dur = 650;
  function tick(now) {
    const u = Math.min(1, (now - t0) / dur);
    const eased = u < 0.5 ? 2 * u * u : 1 - Math.pow(-2 * u + 2, 2) / 2;
    const val = start + (end - start) * eased;
    forceSlider.value = val.toFixed(2);
    if (u >= 1) {
      forceSlider.value = end.toFixed(2);
      loadingModeState = step.state.loadingMode;
    }
    updateFigure();
    if (u < 1) tweenRAF = requestAnimationFrame(tick);
  }
  tweenRAF = requestAnimationFrame(tick);
}
window.goToStep = goToStep;

