userContent.text:
Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<div><strong>Axial loading of a rod</strong></div>
<div id="loadingMode">
  <span>Explain panel</span>
  <button id="modeTension" class="active">Tension (a)</button>
  <button id="modeCompression">Compression (b)</button>
</div>
<label>
  Applied force magnitude
  <input id="appliedForce" type="range" min="0" max="1" step="0.02" value="0.55">
  <span id="forceReadout">|F| = 0.55</span>
</label>
<div>
  <button id="step0">Step 1</button>
  <button id="step1">Step 2</button>
  <button id="step2">Step 3</button>
</div>
<div id="stepTitle" style="font-weight:bold;">Compare tension and compression</div>
<div id="stepNarration" style="line-height:1.35;">Both panels remain visible. Dashed levels show the changed end position relative to the solid original length L₀.</div>
<div style="font-size:11px;line-height:1.35;">ΔL = F L₀ / (Y A), with constant cross-sectional area A.</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// tension solid rod → translucent vertical CylinderGeometry at left, original length L0
// compression solid rod → translucent vertical CylinderGeometry at right, original length L0
// solid top and bottom rims → circular Line loops on each rod end
// solid top faces → horizontal CircleGeometry disks on both rods
// tension dashed deformation level → dashed circular Line above the solid top
// compression dashed deformation level → dashed circular Line inside the rod below the solid top
// axial forces → four red cylinder-and-cone arrows, outward for tension and inward for compression
// L0 dimension brackets → black vertical Line/tick groups from bottom to solid top for each panel
// ΔL dimension brackets → black vertical Line/tick groups from solid top to dashed level for each panel
// area leader → black curved Line with cone arrowhead pointing to compression top face
// labels → addLabel entries for four vector F labels, two L₀ labels, two ΔL labels, A, and panel marks (a),(b)

const R = 0.34;
const L0 = 2.55;
const BOTTOM_Y = -1.20;
const TOP_Y = BOTTOM_Y + L0;
const DELTA_SCALE = 0.42;
const FRONT_Z = R + 0.11;
const xTension = -0.78;
const xCompression = 0.82;

const pale = 0xd7def3;
const rimColor = 0x8295b5;
const redColor = 0xc9343a;
const blackColor = 0x111111;

let focusPanel = 'tension';
let labelEntries = null;
let tweenRAF = null;

const figureGroup = new THREE.Group();
scene.add(figureGroup);

const dimMat = new THREE.LineBasicMaterial({ color: blackColor, depthTest: false });
const leaderMat = new THREE.LineBasicMaterial({ color: blackColor, depthTest: false });
const rimMat = new THREE.LineBasicMaterial({ color: rimColor, depthTest: false });
const dashMat = new THREE.LineDashedMaterial({
  color: rimColor,
  dashSize: 0.055,
  gapSize: 0.038,
  depthTest: false
});
const redMat = new THREE.MeshBasicMaterial({ color: redColor, depthTest: false });
const topMat = new THREE.MeshBasicMaterial({
  color: pale,
  transparent: true,
  opacity: 0.74,
  side: THREE.DoubleSide,
  depthWrite: false
});

function makeSideMaterial() {
  return new THREE.MeshBasicMaterial({
    vertexColors: true,
    transparent: true,
    opacity: 0.82,
    side: THREE.DoubleSide,
    depthWrite: false
  });
}

function makeSideGeometry() {
  const geom = new THREE.CylinderGeometry(R, R, L0, 96, 22, true);
  const pos = geom.attributes.position;
  const base = new THREE.Color('#d6ddf2');
  const colors = [];
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i);
    const z = pos.getZ(i);
    const sideShade = 0.78 + 0.23 * (1 - Math.min(1, Math.abs(x) / R));
    const frontLift = z > 0 ? 1.04 : 0.92;
    colors.push(
      Math.min(1, base.r * sideShade * frontLift),
      Math.min(1, base.g * sideShade * frontLift),
      Math.min(1, base.b * sideShade * frontLift)
    );
  }
  geom.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
  geom.computeVertexNormals();
  return geom;
}

function replaceLinePoints(line, pts, dashed = false) {
  const old = line.geometry;
  line.geometry = new THREE.BufferGeometry().setFromPoints(pts);
  old?.dispose?.();
  if (dashed) line.computeLineDistances();
}

function circlePts(cx, y, zc = 0, radius = R) {
  const pts = [];
  const n = 160;
  for (let i = 0; i <= n; i++) {
    const a = (i / n) * Math.PI * 2;
    pts.push(new THREE.Vector3(cx + radius * Math.cos(a), y, zc + radius * Math.sin(a)));
  }
  return pts;
}

function makeCircleLine(cx, y, material, dashed = false) {
  const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints(circlePts(cx, y)), material);
  if (dashed) line.computeLineDistances();
  line.renderOrder = 20;
  return line;
}

function makeBracket() {
  const g = new THREE.Group();
  const v = new THREE.Line(new THREE.BufferGeometry(), dimMat);
  const t0 = new THREE.Line(new THREE.BufferGeometry(), dimMat);
  const t1 = new THREE.Line(new THREE.BufferGeometry(), dimMat);
  g.add(v, t0, t1);
  g.userData = { v, t0, t1 };
  g.renderOrder = 40;
  figureGroup.add(g);
  return g;
}

function updateBracket(g, x, yA, yB, tick = 0.18) {
  replaceLinePoints(g.userData.v, [
    new THREE.Vector3(x, yA, FRONT_Z),
    new THREE.Vector3(x, yB, FRONT_Z)
  ]);
  replaceLinePoints(g.userData.t0, [
    new THREE.Vector3(x - tick / 2, yA, FRONT_Z),
    new THREE.Vector3(x + tick / 2, yA, FRONT_Z)
  ]);
  replaceLinePoints(g.userData.t1, [
    new THREE.Vector3(x - tick / 2, yB, FRONT_Z),
    new THREE.Vector3(x + tick / 2, yB, FRONT_Z)
  ]);
}

function makeArrow() {
  const g = new THREE.Group();
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.018, 0.018, 0.2, 20), redMat);
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.065, 0.17, 28), redMat);
  shaft.renderOrder = cone.renderOrder = 50;
  g.add(shaft, cone);
  figureGroup.add(g);
  return { group: g, shaft, cone };
}

function setArrow(arrow, x, z, tailY, tipY) {
  const len = Math.abs(tipY - tailY);
  const sign = tipY >= tailY ? 1 : -1;
  const coneLen = Math.min(0.17, len * 0.42);
  const shaftLen = Math.max(0.001, len - coneLen);
  const baseY = tipY - sign * coneLen;

  arrow.group.visible = len > 0.04;
  arrow.shaft.geometry.dispose();
  arrow.shaft.geometry = new THREE.CylinderGeometry(0.018, 0.018, shaftLen, 20);
  arrow.shaft.position.set(x, (tailY + baseY) / 2, z);
  arrow.cone.position.set(x, tipY - sign * coneLen / 2, z);
  arrow.cone.rotation.set(sign > 0 ? 0 : Math.PI, 0, 0);
}

function makeRodPanel(cx) {
  const side = new THREE.Mesh(makeSideGeometry(), makeSideMaterial());
  side.position.set(cx, BOTTOM_Y + L0 / 2, 0);
  side.renderOrder = 2;
  figureGroup.add(side);

  const topDisk = new THREE.Mesh(new THREE.CircleGeometry(R, 128), topMat.clone());
  topDisk.rotation.x = -Math.PI / 2;
  topDisk.position.set(cx, TOP_Y, 0);
  topDisk.renderOrder = 5;
  figureGroup.add(topDisk);

  const bottomDisk = new THREE.Mesh(new THREE.CircleGeometry(R, 128), topMat.clone());
  bottomDisk.rotation.x = -Math.PI / 2;
  bottomDisk.position.set(cx, BOTTOM_Y, 0);
  bottomDisk.renderOrder = 3;
  figureGroup.add(bottomDisk);

  const topRim = makeCircleLine(cx, TOP_Y, rimMat);
  const bottomRim = makeCircleLine(cx, BOTTOM_Y, rimMat);
  figureGroup.add(topRim, bottomRim);

  return { side, topDisk, bottomDisk, topRim, bottomRim };
}

const tensionRod = makeRodPanel(xTension);
const compressionRod = makeRodPanel(xCompression);

const tensionDash = makeCircleLine(xTension, TOP_Y + DELTA_SCALE * 0.55, dashMat, true);
const compressionDash = makeCircleLine(xCompression, TOP_Y - DELTA_SCALE * 0.55, dashMat, true);
figureGroup.add(tensionDash, compressionDash);

const tensionGuideL = new THREE.Line(new THREE.BufferGeometry(), dashMat);
const tensionGuideR = new THREE.Line(new THREE.BufferGeometry(), dashMat);
tensionGuideL.renderOrder = tensionGuideR.renderOrder = 25;
figureGroup.add(tensionGuideL, tensionGuideR);

const arrowTTop = makeArrow();
const arrowTBottom = makeArrow();
const arrowCTop = makeArrow();
const arrowCBottom = makeArrow();

const bracketL0T = makeBracket();
const bracketDLT = makeBracket();
const bracketL0C = makeBracket();
const bracketDLC = makeBracket();

const areaLeader = new THREE.Group();
const areaLine = new THREE.Line(new THREE.BufferGeometry(), leaderMat);
const areaCone = new THREE.Mesh(
  new THREE.ConeGeometry(0.045, 0.13, 20),
  new THREE.MeshBasicMaterial({ color: blackColor, depthTest: false })
);
areaLine.renderOrder = areaCone.renderOrder = 45;
areaLeader.add(areaLine, areaCone);
figureGroup.add(areaLeader);

function updateAreaLeader() {
  const start = new THREE.Vector3(xCompression + 0.55, TOP_Y + 0.30, FRONT_Z + 0.02);
  const control = new THREE.Vector3(xCompression + 0.40, TOP_Y + 0.10, FRONT_Z + 0.02);
  const end = new THREE.Vector3(xCompression + 0.15, TOP_Y + 0.04, R * 0.68);
  const curve = new THREE.QuadraticBezierCurve3(start, control, end);
  const pts = curve.getPoints(36);
  replaceLinePoints(areaLine, pts);
  const tangent = end.clone().sub(pts[pts.length - 2]).normalize();
  areaCone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), tangent);
  areaCone.position.copy(end).sub(tangent.clone().multiplyScalar(0.065));
}

registerInteractive(tensionRod.side, {
  title: 'Panel (a): tension',
  tooltip: 'Tension: outward force, positive ΔL',
  body: 'In tension the equal and opposite forces pull away from the rod. The dashed top is above the solid original top, so the length change ΔL is positive.'
});
registerInteractive(compressionRod.side, {
  title: 'Panel (b): compression',
  tooltip: 'Compression: inward force, shortened rod',
  body: 'In compression the equal and opposite forces press toward the rod. The dashed level inside the rod marks the shortened top position, so ΔL is measured downward from L₀.'
});
registerInteractive(compressionRod.topDisk, {
  title: 'Cross-sectional area A',
  tooltip: 'Area A in the axial-deformation formula',
  body: 'The leader points to the circular cross-section A. For a uniform elastic rod, ΔL = F L₀ / (Y A).'
});

const modeTensionBtn = document.getElementById('modeTension');
const modeCompressionBtn = document.getElementById('modeCompression');
const forceSlider = document.getElementById('appliedForce');
const forceReadout = document.getElementById('forceReadout');
const stepTitleEl = document.getElementById('stepTitle');
const stepNarrationEl = document.getElementById('stepNarration');

function vectorFHTML() {
  return '<span style="display:inline-block;position:relative;padding-top:.32em;font-weight:700;">F<span style="position:absolute;left:.03em;top:-.33em;font-size:.82em;line-height:1;">→</span></span>';
}

function setFocus(panel) {
  focusPanel = panel;
  modeTensionBtn.classList.toggle('active', panel === 'tension');
  modeCompressionBtn.classList.toggle('active', panel === 'compression');
}

function currentMag() {
  return Math.max(0, Math.min(1, parseFloat(forceSlider.value) || 0));
}

function updateFigure() {
  const mag = currentMag();
  const dL = DELTA_SCALE * mag;
  const arrowLen = mag > 0.015 ? 0.36 + 0.42 * mag : 0;
  const tensionDeformedTop = TOP_Y + dL;
  const compressionDeformedTop = TOP_Y - dL;

  replaceLinePoints(tensionDash, circlePts(xTension, tensionDeformedTop), true);
  replaceLinePoints(compressionDash, circlePts(xCompression, compressionDeformedTop), true);

  tensionGuideL.visible = tensionGuideR.visible = dL > 0.012;
  replaceLinePoints(tensionGuideL, [
    new THREE.Vector3(xTension - R, TOP_Y, 0),
    new THREE.Vector3(xTension - R, tensionDeformedTop, 0)
  ], true);
  replaceLinePoints(tensionGuideR, [
    new THREE.Vector3(xTension + R, TOP_Y, 0),
    new THREE.Vector3(xTension + R, tensionDeformedTop, 0)
  ], true);

  setArrow(arrowTTop, xTension, 0, TOP_Y + 0.16, TOP_Y + 0.16 + arrowLen);
  setArrow(arrowTBottom, xTension, 0, BOTTOM_Y - 0.16, BOTTOM_Y - 0.16 - arrowLen);
  setArrow(arrowCTop, xCompression, 0, TOP_Y + 0.18 + arrowLen, TOP_Y + 0.18);
  setArrow(arrowCBottom, xCompression, 0, BOTTOM_Y - 0.18 - arrowLen, BOTTOM_Y - 0.18);

  updateBracket(bracketL0T, xTension - 0.64, BOTTOM_Y, TOP_Y);
  updateBracket(bracketDLT, xTension - 0.64, TOP_Y, tensionDeformedTop);
  updateBracket(bracketL0C, xCompression - 0.58, BOTTOM_Y, TOP_Y);
  updateBracket(bracketDLC, xCompression + 0.58, TOP_Y, compressionDeformedTop);

  bracketDLT.visible = bracketDLC.visible = dL > 0.012;
  updateAreaLeader();

  forceReadout.textContent = `|F| = ${mag.toFixed(2)}`;

  if (labelEntries) {
    labelEntries.ftt.pos.set(xTension + 0.12, TOP_Y + 0.18 + arrowLen * 0.78, FRONT_Z);
    labelEntries.ftb.pos.set(xTension + 0.12, BOTTOM_Y - 0.18 - arrowLen * 0.78, FRONT_Z);
    labelEntries.fct.pos.set(xCompression + 0.12, TOP_Y + 0.18 + arrowLen * 0.72, FRONT_Z);
    labelEntries.fcb.pos.set(xCompression + 0.12, BOTTOM_Y - 0.18 - arrowLen * 0.72, FRONT_Z);

    labelEntries.dlt.pos.set(xTension - 0.82, TOP_Y + dL / 2, FRONT_Z);
    labelEntries.dlc.pos.set(xCompression + 0.78, TOP_Y - dL / 2, FRONT_Z);
    labelEntries.dlt.div.style.visibility = dL > 0.012 ? 'visible' : 'hidden';
    labelEntries.dlc.div.style.visibility = dL > 0.012 ? 'visible' : 'hidden';

    labelEntries.l0t.pos.set(xTension - 0.78, BOTTOM_Y + L0 / 2, FRONT_Z);
    labelEntries.l0c.pos.set(xCompression - 0.72, BOTTOM_Y + L0 / 2, FRONT_Z);
    labelEntries.area.pos.set(xCompression + 0.60, TOP_Y + 0.34, FRONT_Z + 0.02);
  }
}

function goToStep(index) {
  const steps = [
    {
      panel: 'tension',
      force: 0.72,
      title: 'Tension: positive ΔL',
      narration: 'Panel (a) shows outward red forces. The dashed top is above the solid top, and the ΔL bracket runs upward from the L₀ reference level.'
    },
    {
      panel: 'tension',
      force: 0.28,
      title: 'Smaller load: proportional ΔL',
      narration: 'Reducing |F| shortens both ΔL brackets. The solid rods keep the same original length L₀ while the dashed deformation levels move closer to the reference top.'
    },
    {
      panel: 'compression',
      force: 0.72,
      title: 'Compression: shortened level inside',
      narration: 'Panel (b) shows inward red forces. The dashed shortened level lies inside the solid rod, and ΔL is measured downward from the original top.'
    }
  ];
  const step = steps[index];
  if (!step) return;
  if (tweenRAF) cancelAnimationFrame(tweenRAF);
  setFocus(step.panel);
  stepTitleEl.textContent = step.title;
  stepNarrationEl.textContent = step.narration;

  const start = currentMag();
  const end = step.force;
  const t0 = performance.now();
  const dur = 620;
  function tick(now) {
    const u = Math.min(1, (now - t0) / dur);
    const eased = u < 0.5 ? 2 * u * u : 1 - Math.pow(-2 * u + 2, 2) / 2;
    forceSlider.value = (start + (end - start) * eased).toFixed(2);
    updateFigure();
    if (u < 1) tweenRAF = requestAnimationFrame(tick);
  }
  tweenRAF = requestAnimationFrame(tick);
}

